steps.script:
$ErrorActionPreference='Stop'
$o=[ordered]@{audit='tt_windows_all';at=(Get-Date).ToString('o');boot=$null;tasks=@();startup=@();autorun=@();services=@();processes=@();errors=@()}
try{$o.boot=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToString('o')}catch{$o.errors+=('BOOT:'+ $_.Exception.GetType().Name)}
try{
 foreach($t in @(Get-ScheduledTask | Where-Object {($_.TaskName+' '+$_.TaskPath) -match '(?i)TT|SeLoRecordamos|FabCalendar|RainETA|support.bridge|imagen|noticia|tendencia' })){
  $info=$null
  try{$info=Get-ScheduledTaskInfo -TaskName $t.TaskName -TaskPath $t.TaskPath}catch{}
  $exe=@($t.Actions|ForEach-Object{[IO.Path]::GetFileName([string]$_.Execute)}) -join ','
  $o.tasks+=@{name=$t.TaskName;path=$t.TaskPath;state=[string]$t.State;enabled=([string]$t.State -ne 'Disabled');exe=$exe;last=if($info){$info.LastRunTime.ToString('o')}else{''};result=if($info){$info.LastTaskResult}else{$null};next=if($info){$info.NextRunTime.ToString('o')}else{''}}
 }
}catch{$o.errors+=('TASKS:'+ $_.Exception.GetType().Name)}
try{
 foreach($f in @(Get-ChildItem -LiteralPath ([Environment]::GetFolderPath('Startup')) -ErrorAction SilentlyContinue | Where-Object {$_.Name -match '(?i)TT|SeLo|FabCalendar|RainETA|bridge'})){$o.startup+=@{name=$f.Name;kind=$f.Extension}}
}catch{$o.errors+=('STARTUP:'+ $_.Exception.GetType().Name)}
try{
 $k='HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
 $run=Get-ItemProperty -LiteralPath $k -ErrorAction Stop
 foreach($p in @($run.PSObject.Properties|Where-Object {$_.Name -match '(?i)TT|SeLo|FabCalendar|RainETA|bridge'})){$o.autorun+=@{name=$p.Name;present=$true}}
}catch{$o.errors+=('AUTORUN:'+ $_.Exception.GetType().Name)}
try{
 foreach($s in @(Get-CimInstance Win32_Service | Where-Object {($_.Name+' '+$_.DisplayName) -match '(?i)TTActualidad|TTiTTulares|TTendencias|SeLoRecordamos|FabCalendar|RainETA|support.bridge'})){$o.services+=@{name=$s.Name;state=$s.State;start=$s.StartMode}}
}catch{$o.errors+=('SERVICES:'+ $_.Exception.GetType().Name)}
try{
 $ps=@(Get-CimInstance Win32_Process | Where-Object {([string]$_.CommandLine) -match '(?i)TTiTTulares|TTendencias|TTActualidad|SeLoRecordamos|FabCalendar|RainETA|support.bridge|TTImages|TT.Fotos'})
 foreach($p in $ps){
  $cmd=[string]$p.CommandLine
  $role=if($cmd -match '(?i)support.bridge|SupportBridge'){'SupportBridge'}elseif($cmd -match '(?i)editorial_daemon_v2'){'V2 Editorial'}elseif($cmd -match '(?i)image_daemon_v2'){'V2 Images'}elseif($cmd -match '(?i)editorial_run_v2'){'V2 Editorial Worker'}elseif($cmd -match '(?i)image_worker_v2'){'V2 Image Worker'}elseif($cmd -match '(?i)top30.*v2'){'V2 Top30'}elseif($cmd -match '(?i)TTiTTularesDedicatedListener'){'Noticias Listener'}elseif($cmd -match '(?i)TTendenciasDedicatedListener'){'Tendencias Listener'}elseif($cmd -match '(?i)TT.*ImageBridge'){'V1 ImageBridge'}elseif($cmd -match '(?i)TTImages'){'TTImages'}elseif($cmd -match '(?i)SeLoRecordamos'){'SeLoRecordamos'}elseif($cmd -match '(?i)FabCalendar'){'FabCalendar'}elseif($cmd -match '(?i)TT-AutoUpdater'){'Updater'}elseif($cmd -match '(?i)TT.*Watchdog'){'Watchdog'}else{'TT Otro'}
  $o.processes+=@{pid=$p.ProcessId;ppid=$p.ParentProcessId;exe=$p.Name;role=$role;started=([string]$p.CreationDate)}
 }
}catch{$o.errors+=('PROCESSES:'+ $_.Exception.GetType().Name)}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Depth 7 -Compress))
